/* @autogenerated */
import { AVATAR_THEME_WEIGHT, AVATAR_TONES, computeAvatarSpec } from './avatar-text.service';

describe('computeAvatarSpec', () => {
  it('generates initials and aria label', () => {
    const spec = computeAvatarSpec('Luis de la Vega');

    expect(spec.initials).toBe('LV');
    expect(spec.ariaLabel).toBe('Icono de Luis de la Vega');
    expect(spec.bg).toContain('var(--mat-sys-primary-container)');
    expect(spec.fg).toContain('var(--mat-sys-on-primary-container)');
    expect(spec.bg).toContain(`${spec.hue})`);
  });

  it('handles empty text', () => {
    const spec = computeAvatarSpec('');

    expect(spec.initials).toBe('•');
    expect(spec.ariaLabel).toBe('Icono');
  });

  it('uses email local part for initials', () => {
    const spec = computeAvatarSpec('john.doe@example.com');

    expect(spec.initials).toBe('JD');
  });

  it('is deterministic for the same input', () => {
    const first = computeAvatarSpec('Same Name');
    const second = computeAvatarSpec('Same Name');

    expect(second.bg).toBe(first.bg);
    expect(second.fg).toBe(first.fg);
  });

  // Tonos 90 y 30 de varias paletas M3 de Angular Material: primary-container/on-primary-container en claro y oscuro
  const palettes: Record<string, [string, string]> = {
    blue: ['#e0e0ff', '#0000ef'],
    red: ['#ffdad6', '#93000a'],
    green: ['#cbffb8', '#025500'],
    yellow: ['#fff0cd', '#574500'],
    neutral: ['#e3e3e3', '#474747'],
  };

  it('keeps WCAG AA contrast for every hue, theme and mode', () => {
    const weight = AVATAR_THEME_WEIGHT / 100;
    const tone = ([l, c]: readonly number[], h: number): Oklch => [l, c, h];
    let worst = Infinity;
    for (const [tone90, tone30] of Object.values(palettes)) {
      const [light, dark] = [hexToOklch(tone90), hexToOklch(tone30)];
      for (let hue = 0; hue < 360; hue++) {
        const lightBg = mixOklch(light, tone(AVATAR_TONES.light.bg, hue), weight);
        const lightFg = mixOklch(dark, tone(AVATAR_TONES.light.fg, hue), weight);
        const darkBg = mixOklch(dark, tone(AVATAR_TONES.dark.bg, hue), weight);
        const darkFg = mixOklch(light, tone(AVATAR_TONES.dark.fg, hue), weight);
        worst = Math.min(worst, contrast(lightBg, lightFg), contrast(darkBg, darkFg));
      }
    }

    expect(worst).toBeGreaterThanOrEqual(4.5);
  });
});

// Réplica de color-mix(in oklch) y del gamut mapping de CSS Color 4 para medir el contraste que pinta el navegador
type Oklch = [l: number, c: number, h: number];

function hexToOklch(hex: string): Oklch {
  const [r, g, b] = [1, 3, 5].map((i) => {
    const c = parseInt(hex.slice(i, i + 2), 16) / 255;
    return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  const a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const bb = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  return [
    0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
    Math.hypot(a, bb),
    ((Math.atan2(bb, a) * 180) / Math.PI + 360) % 360,
  ];
}

function oklchToLinearRgb([L, C, H]: Oklch): number[] {
  const a = C * Math.cos((H * Math.PI) / 180);
  const b = C * Math.sin((H * Math.PI) / 180);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  return [
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
  ];
}

/** Mezcla con `weight` de `a`, interpolando el tono por el arco más corto (lo que hace color-mix por defecto). */
function mixOklch(a: Oklch, b: Oklch, weight: number): Oklch {
  let dh = b[2] - a[2];
  dh = dh > 180 ? dh - 360 : dh < -180 ? dh + 360 : dh;
  const hue = a[1] < 1e-4 ? b[2] : b[1] < 1e-4 ? a[2] : (a[2] + dh * (1 - weight) + 360) % 360;
  return [a[0] * weight + b[0] * (1 - weight), a[1] * weight + b[1] * (1 - weight), hue];
}

function luminance([L, C, H]: Oklch): number {
  const inGamut = (rgb: number[]) => rgb.every((v) => v >= -1e-4 && v <= 1 + 1e-4);
  // Fuera de sRGB, el navegador reduce el croma manteniendo L y H
  let chroma = C;
  if (!inGamut(oklchToLinearRgb([L, C, H]))) {
    let [lo, hi] = [0, C];
    for (let i = 0; i < 30; i++) {
      const mid = (lo + hi) / 2;
      [lo, hi] = inGamut(oklchToLinearRgb([L, mid, H])) ? [mid, hi] : [lo, mid];
    }
    chroma = lo;
  }
  const [r, g, b] = oklchToLinearRgb([L, chroma, H]).map((v) => Math.min(1, Math.max(0, v)));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function contrast(x: Oklch, y: Oklch): number {
  const [high, low] = [luminance(x), luminance(y)].sort((p, q) => q - p);
  return (high + 0.05) / (low + 0.05);
}
